#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005

int head[MAXN], to[2 * MAXN], nxt[2 * MAXN];
int edge_cnt = 0;

void add_edge(int u, int v) {
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt++;
}

int queue[MAXN];
int parent_node[MAXN];
int sz[MAXN];
int visited[MAXN];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
        sz[i] = 1;
        visited[i] = 0;
    }

    for (int i = 0; i < n - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    int front = 0, back = 0;
    queue[back++] = 1;
    visited[1] = 1;
    parent_node[1] = 0;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (!visited[v]) {
                visited[v] = 1;
                parent_node[v] = u;
                queue[back++] = v;
            }
        }
    }

    int min_diff = n;

    for (int i = n - 1; i > 0; i--) {
        int u = queue[i];
        int p = parent_node[u];
        sz[p] += sz[u];

        int diff = abs(n - 2 * sz[u]);
        if (diff < min_diff) {
            min_diff = diff;
        }
    }

    printf("%d\n", min_diff);

    return 0;
}
